class Solution
{
public:
    int minTotalDistance(vector<vector<int>>& grid)
    {
        vector<int> rows, cols;
        for (int r = 0; r < (int)grid.size(); ++r)
        {
            for (int c = 0; c < (int)grid[r].size(); ++c)
            {
                if (grid[r][c] == 1)
                {
                    rows.push_back(r);
                    cols.push_back(c);
                }
            }
        }
        if (rows.empty())
        {
            return 0;
        }
        sort(cols.begin(), cols.end());
        int mr = rows[rows.size() / 2];
        int mc = cols[cols.size() / 2];
        int result = 0;
        for (int r : rows) {
            result += abs(r - mr);
        }
        for (int c : cols) {
            result += abs(c - mc);
        }
        return result;
    }
};
